import{_ as t,l as i,o as e,c as n,v as r,p as l,x as o,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"RDMA 在 OS 中的位置","description":"","frontmatter":{"title":"RDMA 在 OS 中的位置","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/rdma-os.md","filePath":"cs/rdma-os.md","lastUpdated":1789023840000}'),A={name:"cs/rdma-os.md"};function P(D,a,m,h,_,M){const s=i("Mermaid");return e(),n("div",null,[a[1]||(a[1]=r('<h1 id="rdma-在-os-中的位置" tabindex="-1">RDMA 在 OS 中的位置 <a class="header-anchor" href="#rdma-在-os-中的位置" aria-label="Permalink to &quot;RDMA 在 OS 中的位置&quot;">​</a></h1><div class="epigraph"><p>RDMA 把注册过的用户内存直接交给网卡 DMA，绕过 TCP 与套接字缓冲；内核只做连接、注册与完成队列的映射。</p><footer>—— 据 InfiniBand/RDMA 规范直觉；Linux rdma-core 与 ibverbs 文档；RFC 5040 对 iWARP 的背景</footer></div><p><a href="/cs/zero-copy-network">零拷贝</a> 仍常走 TCP。<a href="/cs/dpdk-kernel-bypass">DPDK</a> 旁路的是整栈。缺口是 <strong>RDMA 在 OS 里的位置</strong>：verbs、MR、QP，以及它不是文件系统的 RDMA 导出百科。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>HPC/存储要微秒级、少拷贝。RDMA：进程注册虚址，卡拿到翻译（或 on-demand paging）；QP 成对，post send/recv 或 RDMA WRITE 不经过对端 CPU。缺口：内核模块（ib_core）管理设备，用户 libibverbs mmap 门铃；与 socket 并行存在，应用要改 API。本课不把 RoCE 拥塞控制写成传输课全文。</p><p><span class="marginnote">rping 一类工具只为证明路径。NVMe-oF RDMA 把块命令放在这套 QP 上，存储栈与网络在此汇合。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>打开设备 → PD → 注册 MR → 建 CQ/QP → 交换 QP 号（TCP 带外）→ post。完成：poll CQ，与 <a href="/cs/nvme-driver">NVMe</a> 同构。对照 TCP：无 sk_buff 数据路径。对照 XDP：XDP 仍以太网；RDMA 是另一种 verbs 设备。</p>',8)),(e(),l(c,null,{default:o(()=>[p(s,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20APP%5B%22ibv_post_send%22%5D%20--%3E%20QP%5B%22%E9%98%9F%E5%88%97%E5%AF%B9%22%5D%0A%20%20MR%5B%22%E6%B3%A8%E5%86%8C%E5%86%85%E5%AD%98%22%5D%20--%3E%20NIC%5B%22RNIC%20DMA%22%5D%0A%20%20QP%20--%3E%20NIC%0A%20%20NIC%20--%3E%20CQ%5B%22%E5%AE%8C%E6%88%90%E9%98%9F%E5%88%97%22%5D%0A%20%20CQ%20--%3E%20POLL%5B%22%E7%94%A8%E6%88%B7%20poll%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>OS 把「安全 DMA 窗口」当成一等资源（MR），把网络变成类似块设备的队列。内核不再逐字节解释流。不要写成量化超低延迟撮合。错误：pin 过多内存会伤页回收——<a href="/cs/rmap">rmap</a> 后课会再遇钉页。</p><p>与 netns：RDMA 设备的 ns 支持不完整于普通网卡，部署要查清。</p><p>实现上：MR 钉页对抗回收，注册过多会让 compaction 失败。QP 状态错误只在 CQ 上看见，应用要把完成当 ABI。RoCE 丢包行为与 InfiniBand 可靠服务不同。 读法上只引用<a href="/cs/zero-copy-network">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「网络栈 / 收发路径」课序里，对象是 <strong>RDMA 在 OS 中的位置</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入全部 QP 状态图。不保证 Soft-RoCE 的性能。网络课序收口于「还有套接字选项这层旋钮」。下一课把 POSIX 套接字选项钉住，作为应用仍走内核 TCP 时的接口。</p><p>版本字段会变，课序钉的是机制对象「RDMA 在 OS 中的位置」，不是某一主线内核的结构体名。 后课默认：RDMA 用 verbs 与注册内存，不经 TCP 数据路径。普通套接字的选项如何改内核行为，下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>RDMA：内核管注册与 QP，数据 DMA 进用户 MR。</li><li>与 socket/DPDK/XDP 是不同接头。</li><li>套接字选项是下一课。</li><li>出处：rdma-core；InfiniBand 直觉；Linux RDMA。</li></ul>',11))])}const C=t(A,[["render",P]]);export{f as __pageData,C as default};
